--   ('0dee4515-8030-441c-bd7c-f1b7418e664b'::uuid, $plre${"title":"Somme et produit des racines","description":"x₁ + x₂ = −b/a et x₁x₂ = c/a sans calculer les racines","variations":[{"blanks":[{"expectedAnswer":"{{eval:-b}}"},{"expectedAnswer":"{{c}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur somme et leur produit.\n\n$x_1+x_2=?$ et $x_1\\times x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"1"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1+x_2=-\\dfrac{b}{a}$ et $x_1\\times x_2=\\dfrac{c}{a}$.","Ici $a=1$ : $x_1+x_2=-b={{eval:-b}}$ et $x_1\\times x_2=c={{c}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:-b/a}}"},{"expectedAnswer":"{{eval:c/a}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur somme et leur produit.\n\n$x_1+x_2=?$ et $x_1\\times x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..5;±"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1+x_2=-\\dfrac{b}{a}$ et $x_1\\times x_2=\\dfrac{c}{a}$.","$$x_1+x_2=-\\dfrac{b}{a}=\\dfrac{ {{eval:-b}} }{ {{a}} }={{eval:-b/a}} \\qquad x_1\\times x_2=\\dfrac{c}{a}=\\dfrac{ {{c}} }{ {{a}} }={{eval:c/a}}$$"]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["5","3"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-5","c":"3"},"description":"x^2-5x+3 : S=5, P=3","variationIndex":0},{"answers":["-5","3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"S = b (signe oublié)","variationIndex":0},{"answers":["3","5"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"somme et produit échangés","variationIndex":0},{"answers":["-3","-7"],"expected":{"status":"correct"},"variables":{"a":"1","b":"3","c":"-7"},"description":"x^2+3x-7 : S=−3, P=−7","variationIndex":0},{"answers":["\\frac{7}{2}","\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"2x^2-7x+3 : S=7/2, P=3/2","variationIndex":1},{"answers":["3{,}5","1{,}5"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"décimaux exacts 3,5 et 1,5","variationIndex":1},{"answers":["7","3"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"-7","c":"3"},"description":"−b et c sans diviser par a","variationIndex":1},{"answers":["-\\frac{7}{2}","\\frac{3}{2}"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"-7","c":"3"},"description":"S = b/a (signe)","variationIndex":1},{"answers":["\\frac{3}{2}","-\\frac{9}{4}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"6","c":"9"},"description":"-4x^2+6x+9 : S=3/2, P=−9/4","variationIndex":1},{"answers":["\\frac{6}{4}","-\\frac{9}{4}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedFractions"]},"variables":{"a":"-4","b":"6","c":"9"},"description":"fraction non réduite 6/4","variationIndex":1}]}$plre$::jsonb),
--   ('30b597c3-a350-4027-8c6f-b6678ab0868f'::uuid, $plre${"title":"Bernoulli, binomiale ou géométrique : identifier la loi","description":"Reconnaître la loi d'une variable aléatoire décrite par un énoncé : nombre de succès (binomiale), rang du premier succès (géométrique), indicatrice (Bernoulli), tirages sans remise (aucune des trois)","variations":[{"choices":[{"content":"$\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{6}\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{1}{6}\\right)$"},{"content":"$\\mathcal{B}\\left({{n}}\\,;\\dfrac{5}{6}\\right)$"},{"content":"$\\mathcal{B}\\left(6\\,;\\dfrac{1}{ {{n}} }\\right)$"}],"statement":"On lance ${{n}}$ fois un dé équilibré à six faces et on note $X$ le nombre de $6$ obtenus.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"n","expression":"5..15"}],"correction":{"steps":["On compte le **nombre de succès** (« obtenir $6$ », probabilité $\\dfrac{1}{6}$) dans ${{n}}$ épreuves identiques et indépendantes.","$X$ suit la loi $\\textcolor{{{color:primary.0}}}{\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{6}\\right)}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"$\\mathcal{G}\\left(\\dfrac{1}{6}\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{5}{6}\\right)$"},{"content":"$\\mathcal{B}\\left(6\\,;\\dfrac{1}{6}\\right)$"},{"content":"La loi de Bernoulli de paramètre $\\dfrac{1}{6}$"}],"statement":"On lance un dé équilibré à six faces **jusqu'à** obtenir un $6$ pour la première fois, et on note $X$ le nombre de lancers effectués.\n\nQuelle est la loi de $X$ ?","correction":{"steps":["On répète une épreuve de Bernoulli de succès « obtenir $6$ » ($p=\\dfrac{1}{6}$) et $X$ est le **rang du premier succès**.","$X$ suit la loi géométrique $\\textcolor{{{color:primary.0}}}{\\mathcal{G}\\left(\\dfrac{1}{6}\\right)}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"La loi de Bernoulli de paramètre ${{eval:t/100;d}}$"},{"content":"La loi de Bernoulli de paramètre ${{eval:1-t/100;d}}$"},{"content":"$\\mathcal{G}\\left({{eval:t/100;d}}\\right)$"},{"content":"$\\mathcal{B}\\left(100\\,;{{eval:t/100;d}}\\right)$"}],"statement":"Dans une production, ${{t}}\\,\\%$ des pièces sont défectueuses. On prélève une pièce au hasard et on note $X$ la variable qui vaut $1$ si la pièce est défectueuse, $0$ sinon.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"t","expression":"2..15"}],"correction":{"steps":["$X$ ne prend que les valeurs $1$ (succès) et $0$ (échec), pour **une seule** épreuve.","$X$ suit la loi **de Bernoulli de paramètre** ${{eval:t/100;d}}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"Aucune de ces lois : les tirages ne sont pas indépendants"},{"content":"$\\mathcal{B}\\left(3\\,;\\dfrac{ {{r}} }{ {{eval:r+b}} }\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{ {{r}} }{ {{eval:r+b}} }\\right)$"},{"content":"La loi de Bernoulli de paramètre $\\dfrac{ {{r}} }{ {{eval:r+b}} }$"}],"statement":"Une urne contient ${{r}}$ boules rouges et ${{b}}$ boules blanches. On tire successivement **et sans remise** trois boules, et on note $X$ le nombre de boules rouges obtenues.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"r","expression":"3..6"},{"name":"b","expression":"3..6"}],"correction":{"steps":["Sans remise, la composition de l'urne change à chaque tirage : les épreuves ne sont **pas indépendantes** et la probabilité de « rouge » n'est pas la même à chaque tirage.","Ce n'est donc **ni une loi binomiale, ni une loi géométrique, ni une loi de Bernoulli**."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"n":"10"},"description":"v0 : binomiale","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : géométrique","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : p et 1 − p","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{},"description":"v1 : géométrique","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"v1 : G(5/6)","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"v1 : binomiale","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"t":"4"},"description":"v2 : Bernoulli","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"t":"4"},"description":"v2 : 1 − p","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"b":"5","r":"4"},"description":"v3 : sans remise → aucune","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"b":"5","r":"4"},"description":"v3 : binomiale à tort","variationIndex":3,"selectedChoices":[1]}]}$plre$::jsonb),
--   ('61e2ac1f-c21d-46ce-b5e2-57a72b9680af'::uuid, $plre${"title":"Reconnaître une suite arithmétique ou géométrique à partir de ses premiers termes","description":"Différences constantes, quotients constants, ou ni l'un ni l'autre","variations":[{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"-9..9"},{"name":"r","expression":"2..9;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a+(r)"},{"name":"t2","expression":"eval:a+2*(r)"},{"name":"t3","expression":"eval:a+3*(r)"},{"name":"t4","expression":"eval:a+4*(r)"}],"correction":{"steps":["On calcule la différence entre deux termes consécutifs : elle est toujours la même, $u_1-u_0=u_2-u_1=u_3-u_2=u_4-u_3=\\textcolor{{{color:primary.0}}}{{{r}}}$.","On passe d'un terme au suivant en ajoutant toujours ${{r}}$ : la suite semble **arithmétique**, de raison $r={{r}}$."]},"correctChoiceIndex":["0"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..5;±"},{"name":"q","expression":"2..3;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a*(q)"},{"name":"t2","expression":"eval:a*(q)^2"},{"name":"t3","expression":"eval:a*(q)^3"},{"name":"t4","expression":"eval:a*(q)^4"}],"correction":{"steps":["On calcule le quotient de deux termes consécutifs : il est toujours le même, $\\dfrac{u_1}{u_0}=\\dfrac{u_2}{u_1}=\\dfrac{u_3}{u_2}=\\dfrac{u_4}{u_3}=\\textcolor{{{color:primary.0}}}{{{q}}}$.","Elle n'est pas arithmétique : $u_1-u_0={{eval:t1-(t0)}}$ mais $u_2-u_1={{eval:t2-(t1)}}$.","On passe d'un terme au suivant en multipliant toujours par ${{q}}$ : la suite semble **géométrique**, de raison $q={{q}}$."]},"correctChoiceIndex":["1"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"m","expression":"1..5;±"},{"name":"t0","expression":"eval:16*m"},{"name":"t1","expression":"eval:8*m"},{"name":"t2","expression":"eval:4*m"},{"name":"t3","expression":"eval:2*m"},{"name":"t4","expression":"eval:m"}],"correction":{"steps":["Chaque terme est la moitié du précédent : $\\dfrac{u_1}{u_0}=\\dfrac{u_2}{u_1}=\\dfrac{u_3}{u_2}=\\dfrac{u_4}{u_3}=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{2}}$.","Elle n'est pas arithmétique : $u_1-u_0={{eval:t1-(t0)}}$ mais $u_2-u_1={{eval:t2-(t1)}}$.","Diviser par $2$, c'est multiplier par $\\dfrac{1}{2}$ : la suite semble **géométrique**, de raison $q=\\dfrac{1}{2}$."]},"correctChoiceIndex":["1"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"c","expression":"1..9"},{"name":"t0","expression":"eval:c"},{"name":"t1","expression":"eval:1+c"},{"name":"t2","expression":"eval:4+c"},{"name":"t3","expression":"eval:9+c"},{"name":"t4","expression":"eval:16+c"}],"correction":{"steps":["Les différences ne sont pas constantes : $u_1-u_0=1$, $u_2-u_1=3$, $u_3-u_2=5$… La suite n'est pas arithmétique.","Elle n'est pas géométrique : $\\dfrac{u_1}{u_0}={{eval:(t1)/(t0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(t2)/(t1)}}$.","La suite n'est **ni arithmétique, ni géométrique**."]},"correctChoiceIndex":["2"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"r","expression":"2..6;±"},{"name":"k","expression":"1..2;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a+(r)"},{"name":"t2","expression":"eval:a+2*(r)"},{"name":"t3","expression":"eval:a+3*(r)+(k)"},{"name":"t4","expression":"eval:a+4*(r)+(k)"}],"conditions":["a+r != 0","a+2*r != 0"],"correction":{"steps":["Les premières différences valent ${{r}}$, mais $u_3-u_2={{eval:t3-(t2)}}$ : la différence n'est pas toujours la même, la suite n'est pas arithmétique.","Elle n'est pas géométrique : $\\dfrac{u_1}{u_0}={{eval:(t1)/(t0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(t2)/(t1)}}$.","La suite n'est **ni arithmétique, ni géométrique**."]},"correctChoiceIndex":["2"]}],"shared":{"choices":[{"content":"arithmétique"},{"content":"géométrique"},{"content":"ni arithmétique, ni géométrique"}]},"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"-4","r":"3","t0":"-4","t1":"-1","t2":"2","t3":"5","t4":"8"},"description":"variation 0 (arithmétique) : « arithmétique » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"-4","r":"3","t0":"-4","t1":"-1","t2":"2","t3":"5","t4":"8"},"description":"variation 0 (arithmétique) : « géométrique » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"-4","r":"3","t0":"-4","t1":"-1","t2":"2","t3":"5","t4":"8"},"description":"variation 0 (arithmétique) : « ni arithmétique, ni géométrique » refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"3","q":"-2","t0":"3","t1":"-6","t2":"12","t3":"-24","t4":"48"},"description":"variation 1 (géométrique) : « arithmétique » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"3","q":"-2","t0":"3","t1":"-6","t2":"12","t3":"-24","t4":"48"},"description":"variation 1 (géométrique) : « géométrique » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","q":"-2","t0":"3","t1":"-6","t2":"12","t3":"-24","t4":"48"},"description":"variation 1 (géométrique) : « ni arithmétique, ni géométrique » refusé","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"m":"3","t0":"48","t1":"24","t2":"12","t3":"6","t4":"3"},"description":"variation 2 (géométrique de raison 1/2) : « arithmétique » refusé","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"m":"3","t0":"48","t1":"24","t2":"12","t3":"6","t4":"3"},"description":"variation 2 (géométrique de raison 1/2) : « géométrique » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"m":"3","t0":"48","t1":"24","t2":"12","t3":"6","t4":"3"},"description":"variation 2 (géométrique de raison 1/2) : « ni arithmétique, ni géométrique » refusé","variationIndex":2,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"c":"2","t0":"2","t1":"3","t2":"6","t3":"11","t4":"18"},"description":"variation 3 (n² + c) : « arithmétique » refusé","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"c":"2","t0":"2","t1":"3","t2":"6","t3":"11","t4":"18"},"description":"variation 3 (n² + c) : « géométrique » refusé","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"c":"2","t0":"2","t1":"3","t2":"6","t3":"11","t4":"18"},"description":"variation 3 (n² + c) : « ni arithmétique, ni géométrique » accepté","variationIndex":3,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"5","k":"1","r":"-2","t0":"5","t1":"3","t2":"1","t3":"0","t4":"-2"},"description":"variation 4 (différence irrégulière) : « arithmétique » refusé","variationIndex":4,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"5","k":"1","r":"-2","t0":"5","t1":"3","t2":"1","t3":"0","t4":"-2"},"description":"variation 4 (différence irrégulière) : « géométrique » refusé","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"5","k":"1","r":"-2","t0":"5","t1":"3","t2":"1","t3":"0","t4":"-2"},"description":"variation 4 (différence irrégulière) : « ni arithmétique, ni géométrique » accepté","variationIndex":4,"selectedChoices":[2]}]}$plre$::jsonb),
--   ('d2943133-ebf7-424d-946a-8fed6cfa76be'::uuid, $plre${"title":"Reconnaître une suite arithmétique ou géométrique à partir de sa forme explicite","description":"u(n) = an + b, u(n) = u(0) × qⁿ, ou ni l'un ni l'autre (n² + c, kⁿ + c)","variations":[{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{eval:a*n+b}}$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"n","expression":"n|n"},{"name":"a","expression":"1..9;±"},{"name":"b","expression":"-9..9"}],"correction":{"steps":["$$u_{n+1}-u_n={{a}}(n+1){{eval:b;+}}-({{eval:a*n+b}})$$ soit $u_{n+1}-u_n=\\textcolor{{{color:primary.0}}}{{{a}}}$.","La différence ne dépend pas de $n$ : la suite est **arithmétique**, de raison $r={{a}}$ et de premier terme $u_0={{b}}$."]},"correctChoiceIndex":["0"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{b}}-{{a}}n$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"n","expression":"n|n"},{"name":"a","expression":"1..9"},{"name":"b","expression":"0..9"}],"correction":{"steps":["$$u_{n+1}-u_n={{b}}-{{a}}(n+1)-({{b}}-{{a}}n)$$ soit $u_{n+1}-u_n=\\textcolor{{{color:primary.0}}}{-{{a}}}$.","La différence ne dépend pas de $n$ : la suite est **arithmétique**, de raison $r=-{{a}}$ et de premier terme $u_0={{b}}$."]},"correctChoiceIndex":["0"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{a}}*{{q}}^n$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"q","expression":"2..5"}],"correction":{"steps":["$${u_{n+1}}/{u_n}={ {{a}}*{{q}}^{n+1} }/{ {{a}}*{{q}}^n }$$ soit $\\dfrac{u_{n+1}}{u_n}=\\textcolor{{{color:primary.0}}}{{{q}}}$.","On passe d'un terme au suivant en multipliant toujours par ${{q}}$ : la suite est **géométrique**, de raison $q={{q}}$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{a}}*{{q}}^n$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"q","expression":"0.5|0.2|0.1|0.9"}],"correction":{"steps":["$${u_{n+1}}/{u_n}={ {{a}}*{{q}}^{n+1} }/{ {{a}}*{{q}}^n }$$ soit $\\dfrac{u_{n+1}}{u_n}=\\textcolor{{{color:primary.0}}}{{{q}}}$.","On passe d'un terme au suivant en multipliant toujours par ${{q}}$ : la suite est **géométrique**, de raison $q={{q}}$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n=n^2+{{c}}$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"c","expression":"1..9"},{"name":"u0","expression":"eval:c"},{"name":"u1","expression":"eval:1+c"},{"name":"u2","expression":"eval:4+c"}],"correction":{"steps":["$$u_{n+1}-u_n=(n+1)^2+{{c}}-\\left(n^2+{{c}}\\right)=n^2+2n+1-n^2=2n+1$$","La différence **dépend de $n$** : la suite n'est pas arithmétique.","On calcule les premiers termes : $u_0={{u0}}$, $u_1={{u1}}$ et $u_2={{u2}}$. Comme $\\dfrac{u_1}{u_0}={{eval:(u1)/(u0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(u2)/(u1)}}$, la suite n'est pas géométrique.","La suite n'est **ni arithmétique, ni géométrique**."]},"correctChoiceIndex":["2"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{k}}^n+{{c}}$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"n","expression":"n|n"},{"name":"k","expression":"2..3"},{"name":"c","expression":"1..9"},{"name":"u0","expression":"eval:1+c"},{"name":"u1","expression":"eval:k+c"},{"name":"u2","expression":"eval:k^2+c"}],"correction":{"steps":["$$u_{n+1}-u_n={{k}}^{n+1}+{{c}}-\\left({{k}}^n+{{c}}\\right)={{k}}^{n+1}-{{k}}^n={{k}}^n\\times\\left({{k}}-1\\right)$$","La différence **dépend de $n$** : la suite n'est pas arithmétique.","On calcule les premiers termes : $u_0={{u0}}$, $u_1={{u1}}$ et $u_2={{u2}}$. Comme $\\dfrac{u_1}{u_0}={{eval:(u1)/(u0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(u2)/(u1)}}$, la suite n'est pas géométrique.","Attention : à cause du « $+{{c}}$ », ce n'est pas la forme $u_0\\times q^n$. La suite n'est **ni arithmétique, ni géométrique**."]},"correctChoiceIndex":["2"]}],"shared":{"choices":[{"content":"arithmétique"},{"content":"géométrique"},{"content":"ni arithmétique, ni géométrique"}],"cleanCoefficients":true},"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"5","b":"-2"},"description":"variation 0 (an + b) : « arithmétique » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"5","b":"-2"},"description":"variation 0 (an + b) : « géométrique » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"5","b":"-2"},"description":"variation 0 (an + b) : « ni arithmétique, ni géométrique » refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"a":"3","b":"4"},"description":"variation 1 (b − an) : « arithmétique » accepté","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"3","b":"4"},"description":"variation 1 (b − an) : « géométrique » refusé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","b":"4"},"description":"variation 1 (b − an) : « ni arithmétique, ni géométrique » refusé","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"3","q":"2"},"description":"variation 2 (a × qⁿ) : « arithmétique » refusé","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"3","q":"2"},"description":"variation 2 (a × qⁿ) : « géométrique » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","q":"2"},"description":"variation 2 (a × qⁿ) : « ni arithmétique, ni géométrique » refusé","variationIndex":2,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"7","q":"0.5"},"description":"variation 3 (a × 0,5ⁿ) : « arithmétique » refusé","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"7","q":"0.5"},"description":"variation 3 (a × 0,5ⁿ) : « géométrique » accepté","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"7","q":"0.5"},"description":"variation 3 (a × 0,5ⁿ) : « ni arithmétique, ni géométrique » refusé","variationIndex":3,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"c":"1","u0":"1","u1":"2","u2":"5"},"description":"variation 4 (n² + c) : « arithmétique » refusé","variationIndex":4,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"c":"1","u0":"1","u1":"2","u2":"5"},"description":"variation 4 (n² + c) : « géométrique » refusé","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"c":"1","u0":"1","u1":"2","u2":"5"},"description":"variation 4 (n² + c) : « ni arithmétique, ni géométrique » accepté","variationIndex":4,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"c":"1","k":"2","u0":"2","u1":"3","u2":"5"},"description":"variation 5 (kⁿ + c) : « arithmétique » refusé","variationIndex":5,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"c":"1","k":"2","u0":"2","u1":"3","u2":"5"},"description":"variation 5 (kⁿ + c) : « géométrique » refusé","variationIndex":5,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"c":"1","k":"2","u0":"2","u1":"3","u2":"5"},"description":"variation 5 (kⁿ + c) : « ni arithmétique, ni géométrique » accepté","variationIndex":5,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"a":"1","b":"3"},"description":"variation 0 (u_n = n + 3, a = 1) : « arithmétique » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"-1","b":"-8"},"description":"variation 0 (u_n = −n − 8, a = −1) : « arithmétique » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"6","b":"0"},"description":"variation 0 (u_n = 6n, b = 0) : « géométrique » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"1","b":"0"},"description":"variation 1 (u_n = −n, a = 1, b = 0) : « arithmétique » accepté","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"1","q":"3"},"description":"variation 2 (u_n = 3^n, a = 1) : « géométrique » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"1","q":"3"},"description":"variation 2 (u_n = 3^n, a = 1) : « ni l'un ni l'autre » refusé","variationIndex":2,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"a":"-1","q":"0.5"},"description":"variation 3 (u_n = −0,5^n, a = −1) : « géométrique » accepté","variationIndex":3,"selectedChoices":[1]}]}$plre$::jsonb),
--   ('f63408c5-ec96-4a17-92bc-15796e0b9a61'::uuid, $plre${"title":"Reconnaître une suite arithmétique ou géométrique à partir de sa relation de récurrence","description":"u(n+1) = u(n) + r, u(n+1) = q u(n), ou ni l'un ni l'autre","variations":[{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}=u_n{{eval:r;+}}$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"-9..9"},{"name":"r","expression":"1..9;±"}],"correction":{"steps":["Pour tout entier naturel $n$, $u_{n+1}-u_n=\\textcolor{{{color:primary.0}}}{{{r}}}$ : on passe d'un terme au suivant en ajoutant toujours le même nombre.","La suite est **arithmétique**, de raison $r={{r}}$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["0"]},{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}={{q}}u_n$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"q","expression":"-5..5!0,1"}],"correction":{"steps":["Pour tout entier naturel $n$, $u_{n+1}=\\textcolor{{{color:primary.0}}}{{{q}}}\\times u_n$ : on passe d'un terme au suivant en multipliant toujours par le même nombre.","La suite est **géométrique**, de raison $q={{q}}$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}=\\dfrac{u_n}{ {{k}} }$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"k","expression":"2..5"}],"correction":{"steps":["Diviser par ${{k}}$, c'est multiplier par $\\dfrac{1}{ {{k}} }$ : pour tout entier naturel $n$, $u_{n+1}=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{ {{k}} }}\\times u_n$.","La suite est **géométrique**, de raison $q=\\dfrac{1}{ {{k}} }$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}={{p}}u_n{{eval:b;+}}$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..5;±"},{"name":"p","expression":"-4..4!0,1"},{"name":"b","expression":"1..9;±"},{"name":"u1","expression":"eval:p*(a)+(b)"},{"name":"u2","expression":"eval:p*(u1)+(b)"}],"conditions":["p*a+b != 0","p*a+b != a"],"correction":{"steps":["Pour passer d'un terme au suivant, on multiplie par ${{p}}$ **puis** on ajoute ${{b}}$ : ce n'est ni seulement une addition, ni seulement une multiplication.","On calcule les premiers termes : $u_1={{u1}}$ et $u_2={{u2}}$.","$u_1-u_0={{eval:u1-(a)}}$ mais $u_2-u_1={{eval:u2-(u1)}}$ : la suite n'est pas arithmétique. $\\dfrac{u_1}{u_0}={{eval:(u1)/(a)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(u2)/(u1)}}$ : elle n'est pas géométrique.","La suite n'est **ni arithmétique, ni géométrique**."]},"correctChoiceIndex":["2"]},{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}=u_n+{{eval:k*n}}$$\n\nCette suite est-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"n","expression":"n|n"},{"name":"a","expression":"1..9"},{"name":"k","expression":"1..3"},{"name":"u1","expression":"eval:a"},{"name":"u2","expression":"eval:a+(k)"}],"correction":{"steps":["On ajoute ${{eval:k*n}}$, qui **dépend de $n$** : on n'ajoute pas toujours le même nombre.","On calcule les premiers termes : $u_1={{u1}}$ et $u_2={{u2}}$.","$u_1-u_0={{eval:u1-(a)}}$ mais $u_2-u_1={{eval:u2-(u1)}}$ : la suite n'est pas arithmétique. $\\dfrac{u_1}{u_0}={{eval:(u1)/(a)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(u2)/(u1)}}$ : elle n'est pas géométrique.","La suite n'est **ni arithmétique, ni géométrique**."]},"correctChoiceIndex":["2"]}],"shared":{"choices":[{"content":"arithmétique"},{"content":"géométrique"},{"content":"ni arithmétique, ni géométrique"}],"cleanCoefficients":true},"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"4","r":"-3"},"description":"variation 0 (u_{n+1} = u_n + r) : « arithmétique » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"4","r":"-3"},"description":"variation 0 (u_{n+1} = u_n + r) : « géométrique » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"4","r":"-3"},"description":"variation 0 (u_{n+1} = u_n + r) : « ni arithmétique, ni géométrique » refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"-2","q":"3"},"description":"variation 1 (u_{n+1} = q u_n) : « arithmétique » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"-2","q":"3"},"description":"variation 1 (u_{n+1} = q u_n) : « géométrique » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"-2","q":"3"},"description":"variation 1 (u_{n+1} = q u_n) : « ni arithmétique, ni géométrique » refusé","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"5","k":"2"},"description":"variation 2 (u_{n+1} = u_n / k) : « arithmétique » refusé","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"5","k":"2"},"description":"variation 2 (u_{n+1} = u_n / k) : « géométrique » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"5","k":"2"},"description":"variation 2 (u_{n+1} = u_n / k) : « ni arithmétique, ni géométrique » refusé","variationIndex":2,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"1","b":"1","p":"2","u1":"3","u2":"7"},"description":"variation 3 (u_{n+1} = p u_n + b) : « arithmétique » refusé","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"1","b":"1","p":"2","u1":"3","u2":"7"},"description":"variation 3 (u_{n+1} = p u_n + b) : « géométrique » refusé","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"1","b":"1","p":"2","u1":"3","u2":"7"},"description":"variation 3 (u_{n+1} = p u_n + b) : « ni arithmétique, ni géométrique » accepté","variationIndex":3,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"3","k":"1","u1":"3","u2":"4"},"description":"variation 4 (u_{n+1} = u_n + kn) : « arithmétique » refusé","variationIndex":4,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"3","k":"1","u1":"3","u2":"4"},"description":"variation 4 (u_{n+1} = u_n + kn) : « géométrique » refusé","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"3","k":"1","u1":"3","u2":"4"},"description":"variation 4 (u_{n+1} = u_n + kn) : « ni arithmétique, ni géométrique » accepté","variationIndex":4,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"a":"3","q":"-1"},"description":"variation 1 (u_{n+1} = −u_n, q = −1) : « géométrique » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","q":"-1"},"description":"variation 1 (u_{n+1} = −u_n, q = −1) : « arithmétique » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"5","b":"2","p":"-1"},"description":"variation 3 (u_{n+1} = −u_n + 2, p = −1) : « ni l'un ni l'autre » accepté","variationIndex":3,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"5","b":"2","p":"-1"},"description":"variation 3 (u_{n+1} = −u_n + 2, p = −1) : « arithmétique » refusé","variationIndex":3,"selectedChoices":[0]}]}$plre$::jsonb)
