set local lock_timeout = '5s';

-- ---- 1. Le lot, en tables temporaires -----------------------------------------------------
drop table if exists pg_temp._plre_modeles;
create temporary table _plre_modeles (
	id uuid primary key,
	branche text not null, notion text not null, sous_notion text,
	grades text[] not null,
	-- Statut relevé : les neufs en héritent (un brouillon publié depuis publierait ses neufs).
	statut text not null,
	avant jsonb not null, apres jsonb not null,
	-- Nœud d'arrivée (R2 : les points du modèle vivent ailleurs) ; null : il ne bouge pas.
	branche_apres text, notion_apres text, sous_notion_apres text
);
insert into _plre_modeles values ('0dee4515-8030-441c-bd7c-f1b7418e664b', $plre$Fonctions$plre$, $plre$Second degré$plre$, $plre$somme et produit des racines$plre$, array['1_SPE'], 'draft',
  $plre${"title":"Somme et produit des racines","description":"x₁ + x₂ = −b/a et x₁x₂ = c/a sans calculer les racines","variations":[{"blanks":[{"expectedAnswer":"{{eval:-b}}"},{"expectedAnswer":"{{c}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur somme et leur produit.\n\n$x_1+x_2=?$ et $x_1\\times x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"1"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1+x_2=-\\dfrac{b}{a}$ et $x_1\\times x_2=\\dfrac{c}{a}$.","Ici $a=1$ : $x_1+x_2=-b={{eval:-b}}$ et $x_1\\times x_2=c={{c}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:-b/a}}"},{"expectedAnswer":"{{eval:c/a}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur somme et leur produit.\n\n$x_1+x_2=?$ et $x_1\\times x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..5;±"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1+x_2=-\\dfrac{b}{a}$ et $x_1\\times x_2=\\dfrac{c}{a}$.","$$x_1+x_2=-\\dfrac{b}{a}=\\dfrac{ {{eval:-b}} }{ {{a}} }={{eval:-b/a}} \\qquad x_1\\times x_2=\\dfrac{c}{a}=\\dfrac{ {{c}} }{ {{a}} }={{eval:c/a}}$$"]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["5","3"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-5","c":"3"},"description":"x^2-5x+3 : S=5, P=3","variationIndex":0},{"answers":["-5","3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"S = b (signe oublié)","variationIndex":0},{"answers":["3","5"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"somme et produit échangés","variationIndex":0},{"answers":["-3","-7"],"expected":{"status":"correct"},"variables":{"a":"1","b":"3","c":"-7"},"description":"x^2+3x-7 : S=−3, P=−7","variationIndex":0},{"answers":["\\frac{7}{2}","\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"2x^2-7x+3 : S=7/2, P=3/2","variationIndex":1},{"answers":["3{,}5","1{,}5"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"décimaux exacts 3,5 et 1,5","variationIndex":1},{"answers":["7","3"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"-7","c":"3"},"description":"−b et c sans diviser par a","variationIndex":1},{"answers":["-\\frac{7}{2}","\\frac{3}{2}"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"-7","c":"3"},"description":"S = b/a (signe)","variationIndex":1},{"answers":["\\frac{3}{2}","-\\frac{9}{4}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"6","c":"9"},"description":"-4x^2+6x+9 : S=3/2, P=−9/4","variationIndex":1},{"answers":["\\frac{6}{4}","-\\frac{9}{4}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedFractions"]},"variables":{"a":"-4","b":"6","c":"9"},"description":"fraction non réduite 6/4","variationIndex":1}]}$plre$::jsonb,
  $plre${"title":"Somme des racines","description":"x₁ + x₂ = −b/a sans calculer les racines","variations":[{"blanks":[{"expectedAnswer":"{{eval:-b}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur somme.\n\n$x_1+x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"1"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1+x_2=-\\dfrac{b}{a}$.","Ici $a=1$ : $x_1+x_2=-b={{eval:-b}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:-b/a}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur somme.\n\n$x_1+x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..5;±"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1+x_2=-\\dfrac{b}{a}$.","$$x_1+x_2=-\\dfrac{b}{a}=\\dfrac{ {{eval:-b}} }{ {{a}} }={{eval:-b/a}}$$"]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["5"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-5","c":"3"},"description":"x^2-5x+3 : S=5, P=3","variationIndex":0},{"answers":["-5"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"S = b (signe oublié)","variationIndex":0},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"produit donné pour la somme","variationIndex":0},{"answers":["-3"],"expected":{"status":"correct"},"variab