insert into _plre_modeles values ('30b597c3-a350-4027-8c6f-b6678ab0868f', $plre$Probabilités$plre$, $plre$Loi binomiale$plre$, $plre$schéma de Bernoulli$plre$, array['T_SPE', 'T_COMP'], 'draft',
  $plre${"title":"Bernoulli, binomiale ou géométrique : identifier la loi","description":"Reconnaître la loi d'une variable aléatoire décrite par un énoncé : nombre de succès (binomiale), rang du premier succès (géométrique), indicatrice (Bernoulli), tirages sans remise (aucune des trois)","variations":[{"choices":[{"content":"$\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{6}\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{1}{6}\\right)$"},{"content":"$\\mathcal{B}\\left({{n}}\\,;\\dfrac{5}{6}\\right)$"},{"content":"$\\mathcal{B}\\left(6\\,;\\dfrac{1}{ {{n}} }\\right)$"}],"statement":"On lance ${{n}}$ fois un dé équilibré à six faces et on note $X$ le nombre de $6$ obtenus.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"n","expression":"5..15"}],"correction":{"steps":["On compte le **nombre de succès** (« obtenir $6$ », probabilité $\\dfrac{1}{6}$) dans ${{n}}$ épreuves identiques et indépendantes.","$X$ suit la loi $\\textcolor{{{color:primary.0}}}{\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{6}\\right)}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"$\\mathcal{G}\\left(\\dfrac{1}{6}\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{5}{6}\\right)$"},{"content":"$\\mathcal{B}\\left(6\\,;\\dfrac{1}{6}\\right)$"},{"content":"La loi de Bernoulli de paramètre $\\dfrac{1}{6}$"}],"statement":"On lance un dé équilibré à six faces **jusqu'à** obtenir un $6$ pour la première fois, et on note $X$ le nombre de lancers effectués.\n\nQuelle est la loi de $X$ ?","correction":{"steps":["On répète une épreuve de Bernoulli de succès « obtenir $6$ » ($p=\\dfrac{1}{6}$) et $X$ est le **rang du premier succès**.","$X$ suit la loi géométrique $\\textcolor{{{color:primary.0}}}{\\mathcal{G}\\left(\\dfrac{1}{6}\\right)}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"La loi de Bernoulli de paramètre ${{eval:t/100;d}}$"},{"content":"La loi de Bernoulli de paramètre ${{eval:1-t/100;d}}$"},{"content":"$\\mathcal{G}\\left({{eval:t/100;d}}\\right)$"},{"content":"$\\mathcal{B}\\left(100\\,;{{eval:t/100;d}}\\right)$"}],"statement":"Dans une production, ${{t}}\\,\\%$ des pièces sont défectueuses. On prélève une pièce au hasard et on note $X$ la variable qui vaut $1$ si la pièce est défectueuse, $0$ sinon.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"t","expression":"2..15"}],"correction":{"steps":["$X$ ne prend que les valeurs $1$ (succès) et $0$ (échec), pour **une seule** épreuve.","$X$ suit la loi **de Bernoulli de paramètre** ${{eval:t/100;d}}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"Aucune de ces lois : les tirages ne sont pas indépendants"},{"content":"$\\mathcal{B}\\left(3\\,;\\dfrac{ {{r}} }{ {{eval:r+b}} }\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{ {{r}} }{ {{eval:r+b}} }\\right)$"},{"content":"La loi de Bernoulli de paramètre $\\dfrac{ {{r}} }{ {{eval:r+b}} }$"}],"statement":"Une urne contient ${{r}}$ boules rouges et ${{b}}$ boules blanches. On tire successivement **et sans remise** trois boules, et on note $X$ le nombre de boules rouges obtenues.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"r","expression":"3..6"},{"name":"b","expression":"3..6"}],"correction":{"steps":["Sans remise, la composition de l'urne change à chaque tirage : les épreuves ne sont **pas indépendantes** et la probabilité de « rouge » n'est pas la même à chaque tirage.","Ce n'est donc **ni une loi binomiale, ni une loi géométrique, ni une loi de Bernoulli**."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"n":"10"},"description":"v0 : binomiale","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : géométrique","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : p et 1 − p","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{},"description":"v1 : géométrique","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"v1 : G(5/6)","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"v1 : binomiale","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"t":"4"},"description":"v2 : Bernoulli","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"t":"4"},"description":"v2 : 1 − p","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"b":"5","r":"4"},"description":"v3 : sans remise → aucune","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"b":"5","r":"4"},"description":"v3 : binomiale à tort","variationIndex":3,"selectedChoices":[1]}]}$plre$::jsonb,
  $plre${"title":"Loi binomiale ou non : identifier la loi","description":"Nombre de succès dans des épreuves indépendantes (binomiale), tirages sans remise (aucune loi usuelle)","variations":[{"choices":[{"content":"$\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{6}\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{1}{6}\\right)$"},{"content":"$\\mathcal{B}\\left({{n}}\\,;\\dfrac{5}{6}\\right)$"},{"content":"$\\mathcal{B}\\left(6\\,;\\dfrac{1}{ {{n}} }\\right)$"}],"statement":"On lance ${{n}}$ fois un dé équilibré à six faces et on note $X$ le nombre de $6$ obtenus.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"n","expression":"5..15"}],"correction":{"steps":["On compte le **nombre de succès** (« obtenir $6$ », probabilité $\\dfrac{1}{6}$) dans ${{n}}$ épreuves identiques et indépendantes.","$X$ suit la loi $\\textcolor{{{color:primary.0}}}{\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{6}\\right)}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"Aucune de ces lois : les tirages ne sont pas indépendants"},{"content":"$\\mathcal{B}\\left(3\\,;\\dfrac{ {{r}} }{ {{eval:r+b}} }\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{ {{r}} }{ {{eval:r+b}} }\\right)$"},{"content":"La loi de Bernoulli de paramètre $\\dfrac{ {{r}} }{ {{eval:r+b}} }$"}],"statement":"Une urne contient ${{r}}$ boules rouges et ${{b}}$ boules blanches. On tire successivement **et sans remise** trois boules, et on note $X$ le nombre de boules rouges obtenues.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"r","expression":"3..6"},{"name":"b","expression":"3..6"}],"correction":{"steps":["Sans remise, la composition de l'urne change à chaque tirage : les épreuves ne sont **pas indépendantes** et la probabilité de « rouge » n'est pas la même à chaque tirage.","Ce n'est donc **ni une loi binomiale, ni une loi géométrique, ni une loi de Bernoulli**."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"n":"10"},"description":"v0 : binomiale","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : géométrique","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : p et 1 − p","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"b":"5","r":"4"},"description":"v1 : sans remise → aucune","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"b":"5","r":"4"},"description":"v1 : binomiale à tort","variationIndex":1,"selectedChoices":[1]}]}$plre$::jsonb,
  $plre$Probabilités$plre$, $plre$Loi binomiale$plre$, $plre$expression de la loi$plre$);
insert into _plre_modeles values ('61e2ac1f-c21d-46ce-b5e2-57a72b9680af', $plre$Suites$plre$, $plre$Suites arithmétiques$plre$, $plre$définition$plre$, array['1_SPE'], 'draft',
  $plre${"title":"Reconnaître une suite arithmétique ou géométrique à partir de ses premiers termes","description":"Différences constantes, quotients constants, ou ni l'un ni l'autre","variations":[{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"-9..9"},{"name":"r","expression":"2..9;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a+(r)"},{"name":"t2","expression":"eval:a+2*(r)"},{"name":"t3","expression":"eval:a+3*(r)"},{"name":"t4","expression":"eval:a+4*(r)"}],"correction":{"steps":["On calcule la différence entre deux termes consécutifs : elle est toujours la même, $u_1-u_0=u_2-u_1=u_3-u_2=u_4-u_3=\\textcolor{{{color:primary.0}}}{{{r}}}$.","On passe d'un terme au suivant en ajoutant toujours ${{r}}$ : la suite semble **arithmétique**, de raison $r={{r}}$."]},"correctChoiceIndex":["0"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..5;±"},{"name":"q","expression":"2..3;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a*(q)"},{"name":"t2","expression":"eval:a*(q)^2"},{"name":"t3","expression":"eval:a*(q)^3"},{"name":"t4","expression":"eval:a*(q)^4"}],"correction":{"steps":["On calcule le quotient de deux termes consécutifs : il est toujours le même, $\\dfrac{u_1}{u_0}=\\dfrac{u_2}{u_1}=\\dfrac{u_3}{u_2}=\\dfrac{u_4}{u_3}=\\textcolor{{{color:primary.0}}}{{{q}}}$.","Elle n'est pas arithmétique : $u_1-u_0={{eval:t1-(t0)}}$ mais $u_2-u_1={{eval:t2-(t1)}}$.","On passe d'un terme au suivant en multipliant toujours par ${{q}}$ : la suite semble **géométrique**, de raison $q={{q}}$."]},"correctChoiceIndex":["1"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"m","expression":"1..5;±"},{"name":"t0","expression":"eval:16*m"},{"name":"t1","expression":"eval:8*m"},{"name":"t2","expression":"eval:4*m"},{"name":"t3","expression":"eval:2*m"},{"name":"t4","expression":"eval:m"}],"correction":{"steps":["Chaque terme est la moitié du précédent : $\\dfrac{u_1}{u_0}=\\dfrac{u_2}{u_1}=\\dfrac{u_3}{u_2}=\\dfrac{u_4}{u_3}=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{2}}$.","Elle n'est pas arithmétique : $u_1-u_0={{eval:t1-(t0)}}$ mais $u_2-u_1={{eval:t2-(t1)}}$.","Diviser par $2$, c'est multiplier par $\\dfrac{1}{2}$ : la suite semble **géométrique**, de raison $q=\\dfrac{1}{2}$."]},"correctChoiceIndex":["1"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"c","expression":"1..9"},{"name":"t0","expression":"eval:c"},{"name":"t1","expression":"eval:1+c"},{"name":"t2","expression":"eval:4+c"},{"name":"t3","expression":"eval:9+c"},{"name":"t4","expression":"eval:16+c"}],"correction":{"steps":["Les différences ne sont pas constantes : $u_1-u_0=1$, $u_2-u_1=3$, $u_3-u_2=5$… La suite n'est pas arithmétique.","Elle n'est pas géométrique : $\\dfrac{u_1}{u_0}={{eval:(t1)/(t0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(t2)/(t1)}}$.","La suite n'est **ni arithmétique, ni géométrique**."]},"correctChoiceIndex":["2"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle arithmétique, géométrique, ou ni l'un ni l'autre ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"r","expression":"2..6;±"},{"name":"k","expression":"1..2;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a+(r)"},{"name":"t2","expression":"eval:a+2*(r)"},{"name":"t3","expression":"eval:a+3*(r)+(k)"},{"name":"t4","expression":"eval:a+4*(r)+(k)"}],"conditions":["a+r != 0","a+2*r != 0"],"correction":{"steps":["Les premières différences valent ${{r}}$, mais $u_3-u_2={{eval:t3-(t2)}}$ : la différence n'est pas toujours la même, la suite n'est pas arithmétique.","Elle n'est pas géométrique : $\\dfrac{u_1}{u_0}={{eval:(t1)/(t0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(t2)/(t1)}}$.","La suite n'est **ni arithmétique, ni géométrique**."]},"correctChoiceIndex":["2"]}],"shared":{"choices":[{"content":"arithmétique"},{"content":"géométrique"},{"content":"ni arithmétique, ni géométrique"}]},"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"-4","r":"3","t0":"-4","t1":"-1","t2":"2","t3":"5","t4":"8"},"description":"variation 0 (arithmétique) : « arithmétique » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"-4","r":"3","t0":"-4","t1":"-1","t2":"2","t3":"5","t4":"8"},"description":"variation 0 (arithmétique) : « géométrique » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"-4","r":"3","t0":"-4","t1":"-1","t2":"2","t3":"5","t4":"8"},"description":"variation 0 (arithmétique) : « ni arithmétique, ni géométrique » refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"3","q":"-2","t0":"3","t1":"-6","t2":"12","t3":"-24","t4":"48"},"description":"variation 1 (géométrique) : « arithmétiqu