tion 0 (alignés, croissante) : « ni arithmétique, ni géométrique » refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"N":"8","b":"10","r":"3","N1":"9","u0":"10","u1":"7","u2":"4","u3":"1"},"description":"variation 1 (alignés, décroissante) : « arithmétique » accepté","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"N":"8","b":"10","r":"3","N1":"9","u0":"10","u1":"7","u2":"4","u3":"1"},"description":"variation 1 (alignés, décroissante) : « géométrique » refusé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"N":"8","b":"10","r":"3","N1":"9","u0":"10","u1":"7","u2":"4","u3":"1"},"description":"variation 1 (alignés, décroissante) : « ni arithmétique, ni géométrique » refusé","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"N":"5","a":"1","N1":"6","u0":"1","u1":"2","u2":"4","u3":"8"},"description":"variation 2 (doubles) : « arithmétique » refusé","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"N":"5","a":"1","N1":"6","u0":"1","u1":"2","u2":"4","u3":"8"},"description":"variation 2 (doubles) : « géométrique » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"N":"5","a":"1","N1":"6","u0":"1","u1":"2","u2":"4","u3":"8"},"description":"variation 2 (doubles) : « ni arithmétique, ni géométrique » refusé","variationIndex":2,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"N":"6","a":"64","N1":"7","u0":"64","u1":"32","u2":"16","u3":"8"},"description":"variation 3 (moitiés) : « arithmétique » refusé","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"N":"6","a":"64","N1":"7","u0":"64","u1":"32","u2":"16","u3":"8"},"description":"variation 3 (moitiés) : « géométrique » accepté","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"N":"6","a":"64","N1":"7","u0":"64","u1":"32","u2":"16","u3":"8"},"description":"variation 3 (moitiés) : « ni arithmétique, ni géométrique » refusé","variationIndex":3,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"N":"8","c":"4","d":"1","N1":"9","u0":"17","u1":"10","u2":"5","u3":"2"},"description":"variation 4 (descend puis monte) : « arithmétique » refusé","variationIndex":4,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"N":"8","c":"4","d":"1","N1":"9","u0":"17","u1":"10","u2":"5","u3":"2"},"description":"variation 4 (descend puis monte) : « géométrique » refusé","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"N":"8","c":"4","d":"1","N1":"9","u0":"17","u1":"10","u2":"5","u3":"2"},"description":"variation 4 (descend puis monte) : « ni arithmétique, ni géométrique » accepté","variationIndex":4,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"N":"6","c":"1","N1":"7","u0":"1","u1":"2","u2":"5","u3":"10"},"description":"variation 5 (n² + c) : « arithmétique » refusé","variationIndex":5,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"N":"6","c":"1","N1":"7","u0":"1","u1":"2","u2":"5","u3":"10"},"description":"variation 5 (n² + c) : « géométrique » refusé","variationIndex":5,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"N":"6","c":"1","N1":"7","u0":"1","u1":"2","u2":"5","u3":"10"},"description":"variation 5 (n² + c) : « ni arithmétique, ni géométrique » accepté","variationIndex":5,"selectedChoices":[2]}]}$plre$::jsonb,
