rrect"},"variables":{"a":"1","b":"3","c":"-7"},"description":"x^2+3x-7 : S=−3, P=−7","variationIndex":0},{"answers":["\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"2x^2-7x+3 : S=7/2, P=3/2","variationIndex":1},{"answers":["1{,}5"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"décimaux exacts 3,5 et 1,5","variationIndex":1},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"-7","c":"3"},"description":"−b et c sans diviser par a","variationIndex":1},{"answers":["-\\frac{9}{4}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"6","c":"9"},"description":"-4x^2+6x+9 : S=3/2, P=−9/4","variationIndex":1},{"answers":["-\\frac{18}{8}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedFractions"]},"variables":{"a":"-4","b":"6","c":"9"},"description":"fraction non réduite 18/8","variationIndex":1}]}$plre$::jsonb,
