  $plre${"title":"Loi géométrique : identifier la loi","description":"Rang du premier succès dans des épreuves indépendantes (dé à n faces)","variations":[{"choices":[{"content":"$\\mathcal{G}\\left(\\dfrac{1}{ {{n}} }\\right)$"},{"content":"$\\mathcal{G}\\left(\\dfrac{ {{eval:n-1}} }{ {{n}} }\\right)$"},{"content":"$\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{ {{n}} }\\right)$"},{"content":"La loi de Bernoulli de paramètre $\\dfrac{1}{ {{n}} }$"}],"statement":"On lance un dé équilibré à ${{n}}$ faces, numérotées de $1$ à ${{n}}$, **jusqu'à** obtenir un ${{n}}$ pour la première fois, et on note $X$ le nombre de lancers effectués.\n\nQuelle est la loi de $X$ ?","correction":{"steps":["On répète une épreuve de Bernoulli de succès « obtenir ${{n}}$ » ($p=\\dfrac{1}{ {{n}} }$), et $X$ est le **rang du premier succès**.","$X$ suit la loi géométrique $\\textcolor{{{color:primary.0}}}{\\mathcal{G}\\left(\\dfrac{1}{ {{n}} }\\right)}$."]},"correctChoiceIndex":["0"],"variables":[{"name":"n","expression":"4|6|8|10|12|20"}]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"n":"6"},"description":"v0 : n=6, géométrique","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v0 : G(5/6)","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v0 : binomiale","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v0 : Bernoulli","variationIndex":0,"selectedChoices":[3]},{"expected":{"status":"correct"},"variables":{"n":"20"},"description":"v0 : n=20, géométrique","variationIndex":0,"selectedChoices":[0]}]}$plre$::jsonb,
