insert into _plre_neufs values ('77498f1b-3625-4701-aa9c-f6132eb3b4ba', '30b597c3-a350-4027-8c6f-b6678ab0868f', 3,
  $plre${"title":"Loi de Bernoulli : identifier la loi","description":"Variable qui vaut 1 en cas de succès, 0 sinon, sur une seule épreuve","variations":[{"choices":[{"content":"La loi de Bernoulli de paramètre ${{eval:t/100;d}}$"},{"content":"La loi de Bernoulli de paramètre ${{eval:1-t/100;d}}$"},{"content":"$\\mathcal{G}\\left({{eval:t/100;d}}\\right)$"},{"content":"$\\mathcal{B}\\left(100\\,;{{eval:t/100;d}}\\right)$"}],"statement":"Dans une production, ${{t}}\\,\\%$ des pièces sont défectueuses. On prélève une pièce au hasard et on note $X$ la variable qui vaut $1$ si la pièce est défectueuse, $0$ sinon.\n\nQuelle est la loi de $X$ ?","variables":[{"name":"t","expression":"2..15"}],"correction":{"steps":["$X$ ne prend que les valeurs $1$ (succès) et $0$ (échec), pour **une seule** épreuve.","$X$ suit la loi **de Bernoulli de paramètre** ${{eval:t/100;d}}$."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"t":"4"},"description":"v0 : Bernoulli","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"t":"4"},"description":"v0 : 1 − p","variationIndex":0,"selectedChoices":[1]}]}$plre$::jsonb,
