insert into _plre_neufs values ('fcf1057e-da6f-40ce-b40d-5a66830d44b9', '61e2ac1f-c21d-46ce-b5e2-57a72b9680af', 5,
  $plre${"title":"Reconnaître une suite géométrique à partir de ses premiers termes","description":"Quotients constants ou non (suites arithmétiques, ni arithmétiques ni géométriques)","variations":[{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle géométrique ?","variables":[{"name":"a","expression":"-9..9"},{"name":"r","expression":"2..9;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a+(r)"},{"name":"t2","expression":"eval:a+2*(r)"},{"name":"t3","expression":"eval:a+3*(r)"},{"name":"t4","expression":"eval:a+4*(r)"}],"correction":{"steps":["On calcule le quotient de deux termes consécutifs : $\\dfrac{u_1}{u_0}={{eval:(t1)/(t0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(t2)/(t1)}}$.","Le quotient n'est pas toujours le même : la suite ne semble **pas géométrique**."]},"correctChoiceIndex":["1"],"conditions":["a != 0","a+r != 0"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle géométrique ?","variables":[{"name":"a","expression":"1..5;±"},{"name":"q","expression":"2..3;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a*(q)"},{"name":"t2","expression":"eval:a*(q)^2"},{"name":"t3","expression":"eval:a*(q)^3"},{"name":"t4","expression":"eval:a*(q)^4"}],"correction":{"steps":["On calcule le quotient de deux termes consécutifs : il est toujours le même, $\\dfrac{u_1}{u_0}=\\dfrac{u_2}{u_1}=\\dfrac{u_3}{u_2}=\\dfrac{u_4}{u_3}=\\textcolor{{{color:primary.0}}}{{{q}}}$.","On passe d'un terme au suivant en multipliant toujours par ${{q}}$ : la suite semble **géométrique**, de raison $q={{q}}$."]},"correctChoiceIndex":["0"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle géométrique ?","variables":[{"name":"m","expression":"1..5;±"},{"name":"t0","expression":"eval:16*m"},{"name":"t1","expression":"eval:8*m"},{"name":"t2","expression":"eval:4*m"},{"name":"t3","expression":"eval:2*m"},{"name":"t4","expression":"eval:m"}],"correction":{"steps":["Chaque terme est la moitié du précédent : $\\dfrac{u_1}{u_0}=\\dfrac{u_2}{u_1}=\\dfrac{u_3}{u_2}=\\dfrac{u_4}{u_3}=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{2}}$.","Diviser par $2$, c'est multiplier par $\\dfrac{1}{2}$ : la suite semble **géométrique**, de raison $q=\\dfrac{1}{2}$."]},"correctChoiceIndex":["0"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle géométrique ?","variables":[{"name":"c","expression":"1..9"},{"name":"t0","expression":"eval:c"},{"name":"t1","expression":"eval:1+c"},{"name":"t2","expression":"eval:4+c"},{"name":"t3","expression":"eval:9+c"},{"name":"t4","expression":"eval:16+c"}],"correction":{"steps":["On calcule le quotient de deux termes consécutifs : $\\dfrac{u_1}{u_0}={{eval:(t1)/(t0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(t2)/(t1)}}$.","Le quotient n'est pas toujours le même : la suite ne semble **pas géométrique**."]},"correctChoiceIndex":["1"]},{"statement":"Voici les cinq premiers termes d'une suite $(u_n)$, à partir de $u_0$ :\n\n$${{t0}} \\quad ; \\quad {{t1}} \\quad ; \\quad {{t2}} \\quad ; \\quad {{t3}} \\quad ; \\quad {{t4}}$$\n\nD'après ces termes, la suite semble-t-elle géométrique ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"r","expression":"2..6;±"},{"name":"k","expression":"1..2;±"},{"name":"t0","expression":"eval:a"},{"name":"t1","expression":"eval:a+(r)"},{"name":"t2","expression":"eval:a+2*(r)"},{"name":"t3","expression":"eval:a+3*(r)+(k)"},{"name":"t4","expression":"eval:a+4*(r)+(k)"}],"conditions":["a+r != 0","a+2*r != 0"],"correction":{"steps":["On calcule le quotient de deux termes consécutifs : $\\dfrac{u_1}{u_0}={{eval:(t1)/(t0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(t2)/(t1)}}$.","Le quotient n'est pas toujours le même : la suite ne semble **pas géométrique**."]},"correctChoiceIndex":["1"]}],"shared":{"choices":[{"content":"Oui, elle semble géométrique."},{"content":"Non, elle ne semble pas géométrique."}]},"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"-4","r":"3","t0":"-4","t1":"-1","t2":"2","t3":"5","t4":"8"},"description":"v0 : « non » accepté","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"-4","r":"3","t0":"-4","t1":"-1","t2":"2","t3":"5","t4":"8"},"description":"v0 : « oui » refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"3","q":"-2","t0":"3","t1":"-6","t2":"12","t3":"-24","t4":"48"},"description":"v1 : « oui » accepté","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"3","q":"-2","t0":"3","t1":"-6","t2":"12","t3":"-24","t4":"48"},"description":"v1 : « non » refusé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"m":"3","t0":"48","t1":"24","t2":"12","t3":"6","t4":"3"},"description":"v2 : « oui » accepté","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"m":"3","t0":"48","t1":"24","t2":"12","t3":"6","t4":"3"},"description":"v2 : « non » refusé","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"c":"2","t0":"2","t1":"3","t2":"6","t3":"11","t4":"18"},"description":"v3 : « non » accepté","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"c":"2","t0":"2","t1":"3","t2":"6","t3":"11","t4":"18"},"description":"v3 : « oui » refusé","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"5","k":"1","r":"-2","t0":"5","t1":"3","t2":"1","t3":"0","t4":"-2"},"description":"v4 : « non » accepté","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"5","k":"1","r":"-2","t0":"5","t1":"3","t2":"1","t3":"0","t4":"-2"},"description":"v4 : « oui » refusé","variationIndex":4,"selectedChoices":[0]}]}$plre$::jsonb,
  $plre$Suites$plre$, $plre$Suites géométriques$plre$, $plre$définition$plre$);
insert into _plre_neufs values ('70e682f9-9f54-495b-8943-69c8597a5c32', 'c90fa022-9493-4812-adb7-c785babee9d4', 4,
  $plre${"title":"Intérêts simples ou composés : la suite est-elle arithmétique ?","description":"Reconnaître une suite arithmétique dans un placement (intérêts simples), ou non","variations":[{"statement":"On place ${{C}}$ € à **intérêts simples** au taux annuel de ${{t}}\\,\\%$ : chaque année, on ajoute au capital ${{t}}\\,\\%$ du capital **initial**. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"5..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"}],"correction":{"steps":["Chaque année, on ajoute la même somme : ${{t}}\\,\\%$ de ${{C}}$ €, soit $\\dfrac{ {{t}} }{100}\\times{{C}}={{eval:C*t/100}}$ €.","Pour tout $n$ : $u_{n+1}=u_n+{{eval:C*t/100}}$. La suite est **arithmétique** de raison ${{eval:C*t/100}}$."]},"correctChoiceIndex":["0"]},{"statement":"On place ${{C}}$ € à **intérêts composés** au taux annuel de ${{t}}\\,\\%$ : chaque année, les intérêts, égaux à ${{t}}\\,\\%$ du capital **de l'année**, s'ajoutent au capital. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"5..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"}],"correction":{"steps":["Chaque année, les intérêts sont calculés sur le capital **de l'année**, qui augmente : on n'ajoute pas toujours la même somme.","$u_0={{C}}$, $u_1={{eval:C*(1+t/100);d}}$ et $u_2={{eval:C*(1+t/100)^2;d}}$ : $u_1-u_0={{eval:C*t/100;d}}$ mais $u_2-u_1={{eval:C*(1+t/100)*t/100;d}}$.","La suite n'est **pas arithmétique**."]},"correctChoiceIndex":["1"]},{"statement":"On place ${{C}}$ € sur un compte : chaque année, le capital augmente de ${{t}}\\,\\%$, puis la banque prélève ${{f}}$ € de frais. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"10..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"},{"name":"f","expression":"10|15|20|25|30|40|50"},{"name":"a","expression":"eval:C*(1+t/100)-f"},{"name":"b","expression":"eval:a*(1+t/100)-f"}],"conditions":["f != C*t/100"],"correction":{"steps":["Pour tout $n$ : $u_{n+1}={{eval:1+t/100;d}}\\,u_n-{{f}}$.","$u_0={{C}}$, $u_1={{a}}$ et $u_2={{eval:b;d}}$.","$u_1-u_0={{eval:a-C}}$ et $u_2-u_1={{eval:b-a;d}}$ : les écarts ne sont pas constants, la suite n'est pas arithmétique."]},"correctChoiceIndex":["1"]}],"shared":{"choices":[{"content":"Oui, elle est arithmétique."},{"content":"Non, elle n'est pas arithmétique."}]},"test_specs":[{"expected":{"status":"correct"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v0 : « oui » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v0 : « non » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v1 : « non » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v1 : « oui » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"C":"1000","a":"990","b":"979.8","f":"30","k":"10","t":"2"},"description":"v2 : « non » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"C":"1000","a":"990","b":"979.8","f":"30","k":"10","t":"2"},"description":"v2 : « oui » refusé","variationIndex":2,"selectedChoices":[0]}]}$plre$::jsonb,
  null, null, null);
insert into _plre_neufs values ('f3100c29-23bc-4bfe-b353-20f59d07371e', 'c90fa022-9493-4812-adb7-c785babee9d4', 5,
  $plre${"title":"Intérêts simples ou composés : la suite est-elle géométrique ?","description":"Reconnaître une suite géométrique dans un placement (intérêts composés), ou non","variations":[{"statement":"On place ${{C}}$ € à **intérêts simples** au taux annuel de ${{t}}\\,\\%$ : chaque année, on ajoute au capital ${{t}}\\,\\%$ du capital **initial**. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle géométrique ?","variables":[{"name":"k","expression":"5..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"}],"correction":{"steps":["Chaque année, on ajoute la même somme : ${{t}}\\,\\%$ de ${{C}}$ €, soit $\\dfrac{ {{t}} }{100}\\times{{C}}={{eval:C*t/100}}$ €.","$u_0={{C}}$, $u_1={{eval:C+C*t/100}}$ et $u_2={{eval:C+2*C*t/100}}$. Si la suite était géométrique de raison $q$, on aurait $u_1=q\\,u_0$ et $u_2=q\\,u_1$, donc $u_1^2=u_0\\times u_2$. Or $u_1^2={{eval:(C+C*t/100)^2}}$ et $u_0\\times u_2={{eval:C*(C+2*C*t/100)}}$.","La suite n'est **pas géométrique**."]},"correctChoiceIndex":["1"]},{"statement":"On place ${{C}}$ € à **intérêts composés** au taux annuel de ${{t}}\\,\\%$ : chaque année, les intérêts, égaux à ${{t}}\\,\\%$ du capital **de l'année**, s'ajoutent au capital. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle géométrique ?","variables":[{"name":"k","expression":"5..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"}],"correction":{"steps":["Chaque année, le capital augmente de ${{t}}\\,\\%$ : $u_{n+1}=u_n+\\dfrac{ {{t}} }{100}u_n={{eval:1+t/100;d}}\\,u_n$.","On multiplie toujours par le même nombre : la suite est **géométrique** de raison ${{eval:1+t/100;d}}$."]},"correctChoiceIndex":["0"]},{"statement":"On place ${{C}}$ € sur un compte : chaque année, le capital augmente de ${{t}}\\,\\%$, puis la banque prélève ${{f}}$ € de frais. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle géométrique ?","variables":[{"name":"k","expression":"10..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"},{"name":"f","expression":"10|15|20|25|30|40|50"},{"name":"a","expression":"eval:C*(1+t/100)-f"},{"name":"b","expression":"eval:a*(1+t/100)-f"}],"conditions":["f != C*t/100"],"correction":{"steps":["Pour tout $n$ : $u_{n+1}={{eval:1+t/100;d}}\\,u_n-{{f}}$.","$u_0={{C}}$, $u_1={{a}}$ et $u_2={{eval:b;d}}$.","Si elle était géométrique, on aurait $\\dfrac{u_1}{u_0}=\\dfrac{u_2}{u_1}$, c'est-à-dire $u_1^2=u_0\\times u_2$. Or $u_1^2={{eval:a^2}}$ et $u_0\\times u_2={{eval:C*b}}$ : la suite n'est pas géométrique."]},"correctChoiceIndex":["1"]}],"shared":{"choices":[{"content":"Oui, elle est géométrique."},{"content":"Non, elle n'est pas géométrique."}]},"test_specs":[{"expected":{"status":"correct"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v0 : « non » accepté","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v0 : « oui » refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v1 : « oui » accepté","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v1 : « non » refusé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"C":"1000","a":"990","b":"979.8","f":"30","k":"10","t":"2"},"description":"v2 : « non » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"C":"1000","a":"990","b":"979.8","f":"30","k":"10","t":"2"},"description":"v2 : « oui » refusé","variationIndex":2,"selectedChoices":[0]}]}$plre$::jsonb,
