  $plre${"title":"Reconnaître une suite géométrique à partir de sa forme explicite","description":"u(n) = u(0) × qⁿ, ou non : u(n) = an + b, n² + c, kⁿ + c","variations":[{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{eval:a*n+b}}$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"n","expression":"n|n"},{"name":"a","expression":"1..9;±"},{"name":"b","expression":"-9..9"}],"correction":{"steps":["On calcule les premiers termes : $u_0={{b}}$, $u_1={{eval:a+b}}$ et $u_2={{eval:2*a+b}}$.","Si la suite était géométrique de raison $q$, on aurait $u_1=q\\,u_0$ et $u_2=q\\,u_1$, donc $u_1^2=u_0\\times u_2$. Or $u_1^2={{eval:(a+b)^2}}$ et $u_0\\times u_2={{eval:b*(2*a+b)}}$ : la suite n'est **pas géométrique**."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{b}}-{{a}}n$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"n","expression":"n|n"},{"name":"a","expression":"1..9"},{"name":"b","expression":"0..9"}],"correction":{"steps":["On calcule les premiers termes : $u_0={{b}}$, $u_1={{eval:b-a}}$ et $u_2={{eval:b-2*a}}$.","Si la suite était géométrique de raison $q$, on aurait $u_1=q\\,u_0$ et $u_2=q\\,u_1$, donc $u_1^2=u_0\\times u_2$. Or $u_1^2={{eval:(b-a)^2}}$ et $u_0\\times u_2={{eval:b*(b-2*a)}}$ : la suite n'est **pas géométrique**."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{a}}*{{q}}^n$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"q","expression":"2..5"}],"correction":{"steps":["$${u_{n+1}}/{u_n}={ {{a}}*{{q}}^{n+1} }/{ {{a}}*{{q}}^n }$$ soit $\\dfrac{u_{n+1}}{u_n}=\\textcolor{{{color:primary.0}}}{{{q}}}$.","On passe d'un terme au suivant en multipliant toujours par ${{q}}$ : la suite est **géométrique**, de raison $q={{q}}$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["0"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{a}}*{{q}}^n$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"q","expression":"0.5|0.2|0.1|0.9"}],"correction":{"steps":["$${u_{n+1}}/{u_n}={ {{a}}*{{q}}^{n+1} }/{ {{a}}*{{q}}^n }$$ soit $\\dfrac{u_{n+1}}{u_n}=\\textcolor{{{color:primary.0}}}{{{q}}}$.","On passe d'un terme au suivant en multipliant toujours par ${{q}}$ : la suite est **géométrique**, de raison $q={{q}}$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["0"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n=n^2+{{c}}$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"c","expression":"1..9"},{"name":"u0","expression":"eval:c"},{"name":"u1","expression":"eval:1+c"},{"name":"u2","expression":"eval:4+c"}],"correction":{"steps":["On calcule les premiers termes : $u_0={{u0}}$, $u_1={{u1}}$ et $u_2={{u2}}$. Comme $\\dfrac{u_1}{u_0}={{eval:(u1)/(u0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(u2)/(u1)}}$, on ne multiplie pas toujours par le même nombre.","La suite n'est **pas géométrique**."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie, pour tout entier naturel $n$, par :\n\n$$u_n={{k}}^n+{{c}}$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"n","expression":"n|n"},{"name":"k","expression":"2..3"},{"name":"c","expression":"1..9"},{"name":"u0","expression":"eval:1+c"},{"name":"u1","expression":"eval:k+c"},{"name":"u2","expression":"eval:k^2+c"}],"correction":{"steps":["On calcule les premiers termes : $u_0={{u0}}$, $u_1={{u1}}$ et $u_2={{u2}}$. Comme $\\dfrac{u_1}{u_0}={{eval:(u1)/(u0)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(u2)/(u1)}}$, on ne multiplie pas toujours par le même nombre.","Attention : à cause du « $+{{c}}$ », ce n'est pas la forme $u_0\\times q^n$. La suite n'est **pas géométrique**."]},"correctChoiceIndex":["1"]}],"shared":{"choices":[{"content":"Oui, elle est géométrique."},{"content":"Non, elle n'est pas géométrique."}],"cleanCoefficients":true},"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"5","b":"-2"},"description":"v0 : « non » accepté","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"5","b":"-2"},"description":"v0 : « oui » refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"3","b":"4"},"description":"v1 : « non » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","b":"4"},"description":"v1 : « oui » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"3","q":"2"},"description":"v2 : « oui » accepté","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"3","q":"2"},"description":"v2 : « non » refusé","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"7","q":"0.5"},"description":"v3 : « oui » accepté","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"7","q":"0.5"},"description":"v3 : « non » refusé","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"c":"1","u0":"1","u1":"2","u2":"5"},"description":"v4 : « non » accepté","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"c":"1","u0":"1","u1":"2","u2":"5"},"description":"v4 : « oui » refusé","variationIndex":4,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"c":"1","k":"2","u0":"2","u1":"3","u2":"5"},"description":"v5 : « non » accepté","variationIndex":5,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"c":"1","k":"2","u0":"2","u1":"3","u2":"5"},"description":"v5 : « oui » refusé","variationIndex":5,"selectedChoices":[0]}]}$plre$::jsonb,
  $plre$Suites$plre$, $plre$Suites géométriques$plre$, $plre$définition$plre$);
insert into _plre_neufs values ('cea65372-59a4-48b7-adeb-ffd56d6cf8d1', 'f63408c5-ec96-4a17-92bc-15796e0b9a61', 9,
  $plre${"title":"Reconnaître une suite géométrique à partir de sa relation de récurrence","description":"u(n+1) = q u(n) ou u(n)/k, ou non : u(n) + r, p u(n) + b, u(n) + kn","variations":[{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}=u_n{{eval:r;+}}$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"a","expression":"-9..9"},{"name":"r","expression":"1..9;±"}],"correction":{"steps":["Pour passer d'un terme au suivant, on **ajoute** ${{r}}$ : on ne multiplie pas toujours par le même nombre.","On calcule les premiers termes : $u_1={{eval:a+r}}$ et $u_2={{eval:a+2*r}}$.","Si la suite était géométrique de raison $q$, on aurait $u_1=q\\,u_0$ et $u_2=q\\,u_1$, donc $u_1^2=u_0\\times u_2$. Or $u_1^2={{eval:(a+r)^2}}$ et $u_0\\times u_2={{eval:a*(a+2*r)}}$ : la suite n'est **pas géométrique**."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}={{q}}u_n$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"q","expression":"-5..5!0,1"}],"correction":{"steps":["Pour tout entier naturel $n$, $u_{n+1}=\\textcolor{{{color:primary.0}}}{{{q}}}\\times u_n$ : on passe d'un terme au suivant en multipliant toujours par le même nombre.","La suite est **géométrique**, de raison $q={{q}}$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["0"]},{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}=\\dfrac{u_n}{ {{k}} }$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"a","expression":"1..9;±"},{"name":"k","expression":"2..5"}],"correction":{"steps":["Diviser par ${{k}}$, c'est multiplier par $\\dfrac{1}{ {{k}} }$ : pour tout entier naturel $n$, $u_{n+1}=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{ {{k}} }}\\times u_n$.","La suite est **géométrique**, de raison $q=\\dfrac{1}{ {{k}} }$ et de premier terme $u_0={{a}}$."]},"correctChoiceIndex":["0"]},{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}={{p}}u_n{{eval:b;+}}$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"a","expression":"1..5;±"},{"name":"p","expression":"-4..4!0,1"},{"name":"b","expression":"1..9;±"},{"name":"u1","expression":"eval:p*(a)+(b)"},{"name":"u2","expression":"eval:p*(u1)+(b)"}],"conditions":["p*a+b != 0","p*a+b != a"],"correction":{"steps":["Pour passer d'un terme au suivant, on multiplie par ${{p}}$ **puis** on ajoute ${{b}}$ : ce n'est ni seulement une addition, ni seulement une multiplication.","On calcule les premiers termes : $u_1={{u1}}$ et $u_2={{u2}}$.","$\\dfrac{u_1}{u_0}={{eval:(u1)/(a)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(u2)/(u1)}}$ : la suite n'est **pas géométrique**."]},"correctChoiceIndex":["1"]},{"statement":"La suite $(u_n)$ est définie par $u_0={{a}}$ et, pour tout entier naturel $n$ :\n\n$$u_{n+1}=u_n+{{eval:k*n}}$$\n\nCette suite est-elle géométrique ?","variables":[{"name":"n","expression":"n|n"},{"name":"a","expression":"1..9"},{"name":"k","expression":"1..3"},{"name":"u1","expression":"eval:a"},{"name":"u2","expression":"eval:a+(k)"}],"correction":{"steps":["On ajoute ${{eval:k*n}}$, qui **dépend de $n$** : on n'ajoute pas toujours le même nombre.","On calcule les premiers termes : $u_1={{u1}}$ et $u_2={{u2}}$.","$\\dfrac{u_1}{u_0}={{eval:(u1)/(a)}}$ mais $\\dfrac{u_2}{u_1}={{eval:(u2)/(u1)}}$ : la suite n'est **pas géométrique**."]},"correctChoiceIndex":["1"]}],"shared":{"choices":[{"content":"Oui, elle est géométrique."},{"content":"Non, elle n'est pas géométrique."}],"cleanCoefficients":true},"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"4","r":"-3"},"description":"v0 : « non » accepté","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"4","r":"-3"},"description":"v0 : « oui » refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"-2","q":"3"},"description":"v1 : « oui » accepté","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"-2","q":"3"},"description":"v1 : « non » refusé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"5","k":"2"},"description":"v2 : « oui » accepté","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"5","k":"2"},"description":"v2 : « non » refusé","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"1","b":"1","p":"2","u1":"3","u2":"7"},"description":"v3 : « non » accepté","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"1","b":"1","p":"2","u1":"3","u2":"7"},"description":"v3 : « oui » refusé","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"3","k":"1","u1":"3","u2":"4"},"description":"v4 : « non » accepté","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","k":"1","u1":"3","u2":"4"},"description":"v4 : « oui » refusé","variationIndex":4,"selectedChoices":[0]}]}$plre$::jsonb,
  $plre$Suites$plre$, $plre$Suites géométriques$plre$, $plre$définition$plre$);
drop table if exists pg_temp._plre_tags_neufs;
create temporary table _plre_tags_neufs (
	id uuid not null references _plre_neufs (id),
	rang integer not null,
	tag_grade text not null, tag_code text not null
);
